int dup_task_struct(struct task_struct *dst, struct task_struct *src) {
    /* Flush various processor states from the source task */
    flush_ptrace_hw_breakpoint(src);
    flush_fpu(src);
    flush_thread_info(src);

    /* Prepare source state for duplication */
    prepare_task_state(src);

    /* Copy the source task structure to the destination */
    *dst = *src;

    /* Clear specific flags or states in the destination */
    dst->flags &= ~(PF_SUPERPRIV | PF_FORK_CALL);
    dst->fpu_counter = 0;
    clear_thread_flags(dst);

    return 0;
